-- New Leaf Hearing Care: add the Phonak Audéo EON Line section (insert only) to /phonak-hearing-aids/
-- Applies only if the stored page is still exactly what was reviewed.
UPDATE ec_hearing_aids SET content='[{"_type":"block","_key":"k2s0","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2rz","text":"Phonak Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"eon000","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"eon001","text":"Phonak Audéo EON Line","marks":[]}]},{"_type":"block","_key":"eon002","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"eon003","text":"The Phonak Audéo EON Line is Phonak''s newest generation of hearing technology, with clearer speech, longer battery life, and a smaller, lighter design. Released in August 2026, EON replaces the Infinio Ultra line. It runs on the new HYPERSONIC™ chip, which pairs real-time AI sound processing with better power efficiency.","marks":[]}]},{"_type":"block","_key":"eon004","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"eon005","text":"Because EON is built on a new chip, it is new hardware rather than a firmware update. Current Infinio or Infinio Ultra users need new devices to get EON''s features. All EON models are rechargeable and connect to almost any Bluetooth device, with Auracast™ broadcast audio support built in.","marks":[]}]},{"_type":"block","_key":"eon006","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"eon007","text":"Audéo EON R","marks":[]}]},{"_type":"block","_key":"eon008","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"eon009","text":"A versatile, everyday model powered by AutoSense OS™ AI 8.0, which automatically adjusts to changing sound environments. It suits patients with mild to profound hearing loss who want reliable, hands-free performance in daily listening.","marks":[]}]},{"_type":"block","_key":"eon00a","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"eon00b","text":"Audéo EON Sphere","marks":[]}]},{"_type":"block","_key":"eon00c","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"eon00d","text":"The top of the EON range, built for noisy, complex situations. It features Spheric Speech Clarity 3.0, which separates speech from background noise in real time so voices stand out. It is also the smallest device on the EON platform and suits mild to profound hearing loss.","marks":[]}]},{"_type":"block","_key":"eon00e","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"eon00f","text":"CROS EON R","marks":[]}]},{"_type":"block","_key":"eon00g","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"eon00h","text":"The CROS EON R is designed for single-sided hearing loss. It picks up sound on the side with poorer hearing and sends it to the better ear, so patients no longer miss conversations on one side.","marks":[]}]},{"_type":"block","_key":"eon00i","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"eon00j","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"eon00k","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"eon00l","text":"HYPERSONIC™ chip uses 37% less power than the previous generation while keeping full real-time AI performance.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"eon00m","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"eon00n","text":"The EON Sphere is 25% smaller and 20% lighter than the previous Sphere generation, making it more comfortable with glasses or smaller ears.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"eon00o","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"eon00p","text":"Made-For-All connectivity pairs with virtually any Bluetooth device, and Auracast support lets wearers stream audio directly in venues that broadcast it.","marks":[]}],"listItem":"bullet","level":1},{"_type":"block","_key":"k2s2","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2s1","text":"Phonak Infinio Ultra Line","marks":[]}]},{"_type":"block","_key":"k2s4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2s3","text":"The Phonak Infinio Ultra Line represents the next evolution in hearing technology, delivering elevated clarity, efficiency, and adaptability through advanced AI processing. Released in October 2025, this flagship upgrade enhances the foundational Infinio platform with smarter sound recognition, better battery performance, and simplified maintenance.","marks":[]}]},{"_type":"block","_key":"k2s6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2s5","text":"For many existing Phonak users, these improvements can be activated through an in-clinic firmware update, allowing current Infinio or Infinio Sphere devices to perform at an entirely new level without requiring new hardware.","marks":[]}]},{"_type":"block","_key":"k2s8","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2s7","text":"Infinio Ultra R","marks":[]}]},{"_type":"block","_key":"k2sa","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2s9","text":"A flexible, ultra-adaptive model powered by AutoSense OS™ 7.0, designed to automatically adjust to a wide range of environments. Ideal for patients seeking seamless performance in everyday listening.","marks":[]}]},{"_type":"block","_key":"k2sc","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2sb","text":"Infinio Ultra Sphere","marks":[]}]},{"_type":"block","_key":"k2se","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2sd","text":"Engineered for complex and noisy situations, this model features Spheric Speech Clarity 2.0 and the breakthrough DEEPSONIC™ AI chip, the world’s first dedicated processor for real-time speech separation. This allows a clearer understanding of multiple speakers from any direction, even in the most challenging soundscapes.","marks":[]}]},{"_type":"block","_key":"k2sg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2sf","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2si","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sh","text":"AutoSense OS™ 7.0 adapts with 24% greater precision and is trained on 18× more sound scenarios, resulting in smarter environmental transitions and more natural listening.","marks":[]}]},{"_type":"block","_key":"k2sk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sj","text":"Spheric Speech Clarity 2.0 (Ultra Sphere only) enhances speech up to threefold in noisy settings by isolating voices and reducing background interference.","marks":[]}]},{"_type":"block","_key":"k2sm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sl","text":"Listening effort is reduced by up to 35%, supporting long-term comfort and decreasing auditory fatigue.","marks":[]}]},{"_type":"block","_key":"k2so","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2sn","text":"Phonak Virto Infinio","marks":[]}]},{"_type":"block","_key":"k2sq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2sp","text":"Phonak Virto Infinio is a custom in-the-ear (ITE) hearing aid released in 2025, built for those who want powerful performance in a discreet design. Each device is custom-molded to match the shape of your ear, giving you a snug, comfortable fit that lasts all day.","marks":[]}]},{"_type":"block","_key":"k2ss","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2sr","text":"Packed with advanced sound technology, Virto Infinio delivers clear, natural hearing in a small, almost invisible shell, perfect for anyone who wants great sound without drawing attention.","marks":[]}]},{"_type":"block","_key":"k2su","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2st","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2sw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sv","text":"Custom-Made Fit: Each device is individually molded to the shape of your ear, ensuring a secure, comfortable fit that’s easy to wear all day.","marks":[]}]},{"_type":"block","_key":"k2sy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sx","text":"AutoSense OS 6.0: Automatically adjusts settings based on your surroundings, providing seamless hearing whether you’re in quiet, noisy, or dynamic environments.","marks":[]}]},{"_type":"block","_key":"k2t0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sz","text":"Durable & Water-Resistant: Rated IP68 for dust and moisture resistance, making it ideal for active lifestyles and daily wear.","marks":[]}]},{"_type":"block","_key":"k2t2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2t1","text":"Multiple Technology Levels: Available in four tiers (I90, I70, I50, I30) to meet a range of hearing needs and budgets.","marks":[]}]},{"_type":"block","_key":"k2t4","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2t3","text":"Phonak Audéo Sphere","marks":[]}]},{"_type":"block","_key":"k2t6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2t5","text":"The Phonak Audéo Sphere is a modern hearing aid designed to provide clear sound and comfortable listening experiences for people with mild to severe hearing loss. It uses advanced technology to automatically adjust to different environments, helping users hear well in noisy places, during conversations, or when listening to music.","marks":[]}]},{"_type":"block","_key":"k2t8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2t7","text":"One of the key features of the Phonak Audéo Sphere is its rechargeable battery, which can last a full day on a single charge, offering convenience and ease of use. It also connects to smartphones, allowing users to take calls, stream music, and adjust their hearing aids using an app.","marks":[]}]},{"_type":"block","_key":"k2ta","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2t9","text":"This hearing aid is designed to be nearly invisible, fitting comfortably behind the ear, and it comes in a range of colors to match hair or skin tone. Overall, the Phonak Audéo Sphere is ideal for those looking for a reliable, discreet hearing aid with cutting-edge technology.","marks":[]}]},{"_type":"block","_key":"k2tc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tb","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2te","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2td","text":"Dedicated AI chip: Smartly separates speech from noise.","marks":[]}]},{"_type":"block","_key":"k2tg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2tf","text":"Automatic sound adaptation: Automatically adjusts to different listening environments.","marks":[]}]},{"_type":"block","_key":"k2ti","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2th","text":"Connectivity: Connects with smartphones for hands-free calls, streaming, and remote control through an app.","marks":[]}]},{"_type":"block","_key":"k2tk","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2tj","text":"Phonak Audéo™ Infinio","marks":[]}]},{"_type":"block","_key":"k2tm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tl","text":"The Phonak Audéo Infinio is designed to enhance hearing experiences through advanced features like automatic sound adjustment, superior speech recognition in noisy environments, and seamless connectivity to smartphones and other devices.","marks":[]}]},{"_type":"block","_key":"k2to","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tn","text":"Enjoy better speech understanding and reduced listening effort with Phonak Audeo Infinio. It also includes rechargeable battery options and offers a comfortable, discreet fit behind the ear, making it suitable for everyday use. With its innovative technology, it aims to improve sound clarity and provide a personalized listening experience.","marks":[]}]},{"_type":"block","_key":"k2tq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tp","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2ts","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2tr","text":"CROS Compatibility: Compatible with CROS for unilateral hearing loss.","marks":[]}]},{"_type":"block","_key":"k2tu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2tt","text":"Roger Direct Ready: Comes with RogerDirect™ built in to further improve hearing performance in noise and over distance.","marks":[]}]},{"_type":"block","_key":"k2tw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2tv","text":"Connectivity: Allows for up to 8 Bluetooth® enabled devices to be paired while 2 can be simultaneously connected","marks":[]}]},{"_type":"block","_key":"k2ty","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2tx","text":"Phonak CROS Infinio","marks":[]}]},{"_type":"block","_key":"k2u0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tz","text":"The Phonak CROS Infinio is designed for individuals with single-sided deafness, helping them hear sounds from both sides. It transmits sound wirelessly from the non-hearing ear to the hearing ear, enhancing awareness and understanding, especially in noisy environments.","marks":[]}]},{"_type":"block","_key":"k2u2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2u1","text":"The device seamlessly adapts to different listening situations, providing clear and balanced sound. It is comfortable, discreet, and compatible with Phonak hearing aids, ensuring a comprehensive solution for hearing loss on one side.","marks":[]}]},{"_type":"block","_key":"k2u4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2u3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2u6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2u5","text":"On-the-go Hearing: Provides uninterrupted, hands-free calls and streaming across 2x the distance.","marks":[]}]},{"_type":"block","_key":"k2u8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2u7","text":"Rechargeable: Hear with confidence with Phonak CROS Infinio’s long-lasting rechargeable battery.","marks":[]}]},{"_type":"block","_key":"k2ua","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2u9","text":"Universal Connectivity: Universal connectivity allows seamless integration with Bluetooth® devices.","marks":[]}]},{"_type":"block","_key":"k2uc","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2ub","text":"Phonak Audéo Fit™","marks":[]}]},{"_type":"block","_key":"k2ue","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2ud","text":"Phonak Audéo Fit is an advanced hearing aid designed for active lifestyles. With its innovative features, Audéo Fit helps you build healthy habits by tracking distance, steps, activity levels, average wearing time, and heart rate through the myPhonak app. When it is connected to the myPhonak app, it can track and display your current and resting heart rates, as well as an overview of your heart rate on a daily, weekly, monthly, and yearly basis.","marks":[]}]},{"_type":"block","_key":"k2ug","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2uf","text":"Its Bluetooth connectivity allows seamless connection to smartphones, TVs, Roger™ devices, and more. Audéo Fit comes in two performance levels, Premium (P90) and Advanced (P70), ensuring it meets your specific lifestyle needs.","marks":[]}]},{"_type":"block","_key":"k2ui","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2uh","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2uk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2uj","text":"Health Data Tracker: It enables users to track metrics such as distance traveled, steps taken, activity levels, average wearing time of the hearing aid, and heart rate. This is accessed through the myPhonak app, providing users with valuable insights into their overall well-being and helping them to maintain healthy habits.","marks":[]}]},{"_type":"block","_key":"k2um","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2ul","text":"Tap Control: With this innovative feature, users can perform actions such as answering or ending phone calls, adjusting volume levels, changing programs, or activating other settings simply by tapping on their Audéo Fit hearing aid.","marks":[]}]},{"_type":"block","_key":"k2uo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2un","text":"Universal Connectivity: With universal connectivity, you can pair Audéo Fit with Bluetooth®-enabled smartphones, TVs, and Roger™ devices.","marks":[]}]},{"_type":"block","_key":"k2uq","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2up","text":"Phonak Audéo™ Lumity","marks":[]}]},{"_type":"block","_key":"k2us","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2ur","text":"Phonak understands that conversations are at the heart of life, and being able to fully engage in them is like a spark of light. Phonak Lumity was designed to allow speech to shine, even in those challenging listening situations. With the updated AutoSense Operating System (AutoSense OS) 5.0, Lumity was created with artificial intelligence-based machine learning to accurately identify a sound environment. By seamlessly adapting to different listening scenarios, Lumity is designed to maintain natural sound to improve your listening in everyday life.","marks":[]}]},{"_type":"block","_key":"k2uu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2ut","text":"Phonak Audéo Lumity hearing aids are appropriate for fitting mild to profound hearing losses. This device is a receiver-in-the-ear (RITE) model and is currently available in a rechargeable solution. Lumity is the second generation of the world’s first waterproof rechargeable hearing aid. This makes them an ideal hearing solution for people who live an active lifestyle and put their hearing aids to the test!","marks":[]}]},{"_type":"block","_key":"k2uw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2uv","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2uy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2ux","text":"Bluetooth connectivity: Audéo Lumity pairs with the myPhonak app and Bluetooth-enabled devices to help you connect with the world around you.","marks":[]}]},{"_type":"block","_key":"k2v0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2uz","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2v2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2v1","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2v4","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2v3","text":"Phonak Slim","marks":[]}]},{"_type":"block","_key":"k2v6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2v5","text":"The Phonak Slim device offers many of the same features as the Phonak Audéo Lumity but with a redefined design. The unique ergonomic shape of the Slim offers improved comfort and confidence in wearing a RITE style. Slim is crafted to fit naturally nestled behind the ear, even if you wear glasses.","marks":[]}]},{"_type":"block","_key":"k2v8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2v7","text":"Phonak Slim hearing aids are appropriate for fitting mild to severe hearing loss. The device is a receiver-in-the-ear (RITE) style and is currently available in a rechargeable solution.","marks":[]}]},{"_type":"block","_key":"k2va","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2v9","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2vc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vb","text":"Bluetooth connectivity: Phonak Slim pairs with the myPhonak app and Bluetooth-enabled devices to help you connect with the world around you.","marks":[]}]},{"_type":"block","_key":"k2ve","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vd","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2vg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vf","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2vi","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2vh","text":"Phonak CROS Lumity","marks":[]}]},{"_type":"block","_key":"k2vk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vj","text":"Living with single-sided hearing loss or deafness creates several listening challenges. Listening to background noise and locating where sounds are coming from are just a few of the everyday difficulties. The Phonak CROS Lumity opens up a world where you can enjoy conversations no matter where they come from. The newest CROS technology allows you to immerse yourself and live in every moment with a hearing solution designed for those with unaidable hearing loss in one ear.","marks":[]}]},{"_type":"block","_key":"k2vm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vl","text":"A contralateral routing of the signal (CROS) device is worn on an unaidable ear, to pick up sounds and transmit them wirelessly to the hearing aid worn on the better-hearing ear. The compatible Phonak hearing aid receives the signal from the unaidable ear and plays it to the aidable ear. CROS Lumity devices always need to be combined with a compatible hearing aid in order to function.","marks":[]}]},{"_type":"block","_key":"k2vo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vn","text":"The Phonak CROS Lumity hearing aid is appropriate for fitting one-sided hearing loss or single-sided deafness (SSD). This device is currently available in a rechargeable solution. Phonak CROS Lumity can be fitted with an Audéo L-R, Audéo L-RT, Naída L-PR, or Sky L-PR of any performance level.","marks":[]}]},{"_type":"block","_key":"k2vq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vp","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2vs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vr","text":"Bluetooth connectivity: The Phonak CROS Lumity pairs with the myPhonak app and Bluetooth-enabled devices to help you connect with the world around you.","marks":[]}]},{"_type":"block","_key":"k2vu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vt","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2vw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vv","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2vy","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2vx","text":"Phonak Naída Lumity","marks":[]}]},{"_type":"block","_key":"k2w0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vz","text":"The Phonak Naída Lumity hearing aid is the most powerful hearing solution for significant hearing loss. Their newest technology analyzes 700 environmental scans per second, translating to a high-fidelity sound quality that allows you to feel confident in navigating your everyday life. Naída Lumity embraces the power of conversations and delivers robust and reliable volume for individuals with significant hearing loss.","marks":[]}]},{"_type":"block","_key":"k2w2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2w1","text":"Phonak Naída Lumity hearing aids are appropriate for fitting mild to profound hearing losses. They are a behind-the-ear (BTE) style and are currently available in a rechargeable solution, in addition to a size 675 disposable battery in the ultra-power (UP) model.","marks":[]}]},{"_type":"block","_key":"k2w4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2w3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2w6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2w5","text":"Bluetooth connectivity: Naída Lumity pairs with the myPhonak app and Bluetooth-enabled devices to help you connect with the world around you.","marks":[]}]},{"_type":"block","_key":"k2w8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2w7","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2wa","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2w9","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2wc","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2wb","text":"Phonak Sky Lumity","marks":[]}]},{"_type":"block","_key":"k2we","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wd","text":"Children deserve every opportunity to thrive in their various dynamic listening environments. From developing speech to succeeding academically, Phonak understands the importance of hearing in even the littlest of ears. The classroom, home, and extracurricular activities carry different hearing demands. Their state-of-the-art SmartSpeech™ Technology utilizes a variety of features that minimize unwanted sounds and prioritize speech understanding.","marks":[]}]},{"_type":"block","_key":"k2wg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wf","text":"Phonak Sky Lumity hearing aids are appropriate for fitting mild to profound hearing losses. Sky Lumity is a behind-the-ear (BTE) style and is currently available in a rechargeable solution, in addition to a size 675 disposable battery in the ultra-power (UP) model. They also offer Sky Link M, which is a BTE hearing aid designed to support younger children from the very beginning.","marks":[]}]},{"_type":"block","_key":"k2wi","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wh","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2wk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wj","text":"Bluetooth connectivity: Sky Lumity pairs with the myPhonak Junior app and Bluetooth-enabled devices to help you connect with the world around you. Universal connectivity allows your child to enjoy listening to their personal devices.","marks":[]}]},{"_type":"block","_key":"k2wm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wl","text":"Personalization: The myPhonak Junior app is the industry’s only dedicated pediatric app, and empowers children to personalize their hearing experience. It gives children and parents access to wearing time, but also lets children take control of the sound around them and personalize their settings in the real world.","marks":[]}]},{"_type":"block","_key":"k2wo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wn","text":"Tamper-resistant: Phonak provides styles that help keep the battery out of reach of curious fingers.","marks":[]}]},{"_type":"block","_key":"k2wq","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2wp","text":"Phonak Virto Paradise","marks":[]}]},{"_type":"block","_key":"k2ws","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wr","text":"Phonak Virto Paradise is an in-the-ear (ITE) hearing aid designed just for you. This product line is equipped with several features that optimize your hearing experience by minimizing unwanted noise and enhancing speech. The custom-tailored fit allows your hearing aid to mirror the exact shape of your ear, resulting in a more discreet design and easier to wear with glasses.","marks":[]}]},{"_type":"block","_key":"k2wu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wt","text":"Phonak Virto Paradise hearing aids are appropriate for fitting mild to severe hearing losses. It is an ITE model and is currently available in a variety of sizes: in-the-canal (ITC), completely-in-the-canal (CIC), and invisible-in-the-canal (IIC). The model is available in a variety of color choices, including a black design to resemble modern earbuds. There are a variety of disposable battery options to choose from, depending on the size of the device.","marks":[]}]},{"_type":"block","_key":"k2ww","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wv","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2wy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wx","text":"Bluetooth connectivity: Virto Paradise ITE and ITC devices connect to smartphones, TVs, and more to keep up with your busy life. Additionally, you can easily switch between two paired devices with enhanced Bluetooth capabilities. Smaller products, such as the CIC and IIC, offer streaming via Phonak accessories.","marks":[]}]},{"_type":"block","_key":"k2x0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wz","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2x2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2x1","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2x4","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2x3","text":"Assistive Listening Devices & Technology by Phonak","marks":[]}]},{"_type":"block","_key":"k2x6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2x5","text":"Roger On: A unique microphone for everyday use in noise and over distance. It recognizes if speech is coming from the left or right side of the wearer and provides spatial information to complete the picture of your listening environment.","marks":[]}]},{"_type":"block","_key":"k2x8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2x7","text":"Roger Select: Roger Select is a versatile Bluetooth microphone for hearing aids that is ideal for stationary situations where background noise is present. When used as a table mic, it discreetly and automatically selects the person who is talking and seamlessly switches from one talker to another.","marks":[]}]},{"_type":"block","_key":"k2xa","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2x9","text":"Phonak Serenity Choice: High-end hearing protection solution designed to reduce noise and loud sounds while allowing the ear to breathe and maintain relevant sound and speech information.","marks":[]}]},{"_type":"block","_key":"k2xc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2xb","text":"Phonak offers additional accessories to enhance your hearing aid experience:","marks":[]}]},{"_type":"block","_key":"k2xe","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xd","text":"Table Mic II","marks":[]}]},{"_type":"block","_key":"k2xg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xf","text":"Roger Focus II","marks":[]}]},{"_type":"block","_key":"k2xi","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xh","text":"Roger for Education","marks":[]}]},{"_type":"block","_key":"k2xk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xj","text":"Clip-on Mic","marks":[]}]},{"_type":"block","_key":"k2xm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xl","text":"TV Connector","marks":[]}]},{"_type":"block","_key":"k2xo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xn","text":"PartnerMic","marks":[]}]},{"_type":"block","_key":"k2xq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xp","text":"Remote Control","marks":[]}]},{"_type":"block","_key":"k2yg","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2yf","text":"Frequently Asked Questions About Phonak Hearing Aids","marks":[]}]},{"_type":"block","_key":"k2yi","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2yh","text":"What are the different levels of Phonak Lumity?","marks":[]}]},{"_type":"block","_key":"k2yk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2yj","text":"Phonak Lumity offers four different technology levels, including the following: L90, L70, L50, and L30, ranging from the highest to the lowest technology levels, respectively.","marks":[]}]},{"_type":"block","_key":"k2ym","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2yl","text":"What is the difference between Phonak Paradise and Phonak Life hearing aids?","marks":[]}]},{"_type":"block","_key":"k2yo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2yn","text":"The world’s first waterproof rechargeable hearing aid, Audéo Life, combines the hearing performance of Audéo Paradise with a robust new housing that provides additional protection from water and sweat.","marks":[]}]},{"_type":"block","_key":"k2xs","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2xr","text":"Older Phonak Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k2xu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2xt","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k2xw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xv","text":"Phonak Audéo Paradise","marks":[]}]},{"_type":"block","_key":"k2xy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xx","text":"Phonak Naída Paradise","marks":[]}]},{"_type":"block","_key":"k2y0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xz","text":"Phonak CROS Paradise","marks":[]}]},{"_type":"block","_key":"k2y2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y1","text":"Phonak Naída Link Marvel","marks":[]}]},{"_type":"block","_key":"k2y4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y3","text":"Phonak Sky Marvel","marks":[]}]},{"_type":"block","_key":"k2y6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y5","text":"Phonak Audéo Marvel","marks":[]}]},{"_type":"block","_key":"k2y8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y7","text":"Phonak Bolero B","marks":[]}]},{"_type":"block","_key":"k2ya","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y9","text":"Phonak Naída B","marks":[]}]},{"_type":"block","_key":"k2yc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2yb","text":"Phonak Virto B","marks":[]}]},{"_type":"block","_key":"k2ye","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2yd","text":"Phonak Audéo B","marks":[]}]}]', updated_at=datetime('now') WHERE slug='phonak-hearing-aids' AND content='[{"_type":"block","_key":"k2s0","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2rz","text":"Phonak Hearing Aids Available In Colorado","marks":[]}]},{"_type":"block","_key":"k2s2","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2s1","text":"Phonak Infinio Ultra Line","marks":[]}]},{"_type":"block","_key":"k2s4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2s3","text":"The Phonak Infinio Ultra Line represents the next evolution in hearing technology, delivering elevated clarity, efficiency, and adaptability through advanced AI processing. Released in October 2025, this flagship upgrade enhances the foundational Infinio platform with smarter sound recognition, better battery performance, and simplified maintenance.","marks":[]}]},{"_type":"block","_key":"k2s6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2s5","text":"For many existing Phonak users, these improvements can be activated through an in-clinic firmware update, allowing current Infinio or Infinio Sphere devices to perform at an entirely new level without requiring new hardware.","marks":[]}]},{"_type":"block","_key":"k2s8","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2s7","text":"Infinio Ultra R","marks":[]}]},{"_type":"block","_key":"k2sa","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2s9","text":"A flexible, ultra-adaptive model powered by AutoSense OS™ 7.0, designed to automatically adjust to a wide range of environments. Ideal for patients seeking seamless performance in everyday listening.","marks":[]}]},{"_type":"block","_key":"k2sc","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2sb","text":"Infinio Ultra Sphere","marks":[]}]},{"_type":"block","_key":"k2se","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2sd","text":"Engineered for complex and noisy situations, this model features Spheric Speech Clarity 2.0 and the breakthrough DEEPSONIC™ AI chip, the world’s first dedicated processor for real-time speech separation. This allows a clearer understanding of multiple speakers from any direction, even in the most challenging soundscapes.","marks":[]}]},{"_type":"block","_key":"k2sg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2sf","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2si","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sh","text":"AutoSense OS™ 7.0 adapts with 24% greater precision and is trained on 18× more sound scenarios, resulting in smarter environmental transitions and more natural listening.","marks":[]}]},{"_type":"block","_key":"k2sk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sj","text":"Spheric Speech Clarity 2.0 (Ultra Sphere only) enhances speech up to threefold in noisy settings by isolating voices and reducing background interference.","marks":[]}]},{"_type":"block","_key":"k2sm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sl","text":"Listening effort is reduced by up to 35%, supporting long-term comfort and decreasing auditory fatigue.","marks":[]}]},{"_type":"block","_key":"k2so","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2sn","text":"Phonak Virto Infinio","marks":[]}]},{"_type":"block","_key":"k2sq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2sp","text":"Phonak Virto Infinio is a custom in-the-ear (ITE) hearing aid released in 2025, built for those who want powerful performance in a discreet design. Each device is custom-molded to match the shape of your ear, giving you a snug, comfortable fit that lasts all day.","marks":[]}]},{"_type":"block","_key":"k2ss","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2sr","text":"Packed with advanced sound technology, Virto Infinio delivers clear, natural hearing in a small, almost invisible shell, perfect for anyone who wants great sound without drawing attention.","marks":[]}]},{"_type":"block","_key":"k2su","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2st","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2sw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sv","text":"Custom-Made Fit: Each device is individually molded to the shape of your ear, ensuring a secure, comfortable fit that’s easy to wear all day.","marks":[]}]},{"_type":"block","_key":"k2sy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sx","text":"AutoSense OS 6.0: Automatically adjusts settings based on your surroundings, providing seamless hearing whether you’re in quiet, noisy, or dynamic environments.","marks":[]}]},{"_type":"block","_key":"k2t0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2sz","text":"Durable & Water-Resistant: Rated IP68 for dust and moisture resistance, making it ideal for active lifestyles and daily wear.","marks":[]}]},{"_type":"block","_key":"k2t2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2t1","text":"Multiple Technology Levels: Available in four tiers (I90, I70, I50, I30) to meet a range of hearing needs and budgets.","marks":[]}]},{"_type":"block","_key":"k2t4","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2t3","text":"Phonak Audéo Sphere","marks":[]}]},{"_type":"block","_key":"k2t6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2t5","text":"The Phonak Audéo Sphere is a modern hearing aid designed to provide clear sound and comfortable listening experiences for people with mild to severe hearing loss. It uses advanced technology to automatically adjust to different environments, helping users hear well in noisy places, during conversations, or when listening to music.","marks":[]}]},{"_type":"block","_key":"k2t8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2t7","text":"One of the key features of the Phonak Audéo Sphere is its rechargeable battery, which can last a full day on a single charge, offering convenience and ease of use. It also connects to smartphones, allowing users to take calls, stream music, and adjust their hearing aids using an app.","marks":[]}]},{"_type":"block","_key":"k2ta","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2t9","text":"This hearing aid is designed to be nearly invisible, fitting comfortably behind the ear, and it comes in a range of colors to match hair or skin tone. Overall, the Phonak Audéo Sphere is ideal for those looking for a reliable, discreet hearing aid with cutting-edge technology.","marks":[]}]},{"_type":"block","_key":"k2tc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tb","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2te","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2td","text":"Dedicated AI chip: Smartly separates speech from noise.","marks":[]}]},{"_type":"block","_key":"k2tg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2tf","text":"Automatic sound adaptation: Automatically adjusts to different listening environments.","marks":[]}]},{"_type":"block","_key":"k2ti","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2th","text":"Connectivity: Connects with smartphones for hands-free calls, streaming, and remote control through an app.","marks":[]}]},{"_type":"block","_key":"k2tk","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2tj","text":"Phonak Audéo™ Infinio","marks":[]}]},{"_type":"block","_key":"k2tm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tl","text":"The Phonak Audéo Infinio is designed to enhance hearing experiences through advanced features like automatic sound adjustment, superior speech recognition in noisy environments, and seamless connectivity to smartphones and other devices.","marks":[]}]},{"_type":"block","_key":"k2to","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tn","text":"Enjoy better speech understanding and reduced listening effort with Phonak Audeo Infinio. It also includes rechargeable battery options and offers a comfortable, discreet fit behind the ear, making it suitable for everyday use. With its innovative technology, it aims to improve sound clarity and provide a personalized listening experience.","marks":[]}]},{"_type":"block","_key":"k2tq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tp","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2ts","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2tr","text":"CROS Compatibility: Compatible with CROS for unilateral hearing loss.","marks":[]}]},{"_type":"block","_key":"k2tu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2tt","text":"Roger Direct Ready: Comes with RogerDirect™ built in to further improve hearing performance in noise and over distance.","marks":[]}]},{"_type":"block","_key":"k2tw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2tv","text":"Connectivity: Allows for up to 8 Bluetooth® enabled devices to be paired while 2 can be simultaneously connected","marks":[]}]},{"_type":"block","_key":"k2ty","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2tx","text":"Phonak CROS Infinio","marks":[]}]},{"_type":"block","_key":"k2u0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2tz","text":"The Phonak CROS Infinio is designed for individuals with single-sided deafness, helping them hear sounds from both sides. It transmits sound wirelessly from the non-hearing ear to the hearing ear, enhancing awareness and understanding, especially in noisy environments.","marks":[]}]},{"_type":"block","_key":"k2u2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2u1","text":"The device seamlessly adapts to different listening situations, providing clear and balanced sound. It is comfortable, discreet, and compatible with Phonak hearing aids, ensuring a comprehensive solution for hearing loss on one side.","marks":[]}]},{"_type":"block","_key":"k2u4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2u3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2u6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2u5","text":"On-the-go Hearing: Provides uninterrupted, hands-free calls and streaming across 2x the distance.","marks":[]}]},{"_type":"block","_key":"k2u8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2u7","text":"Rechargeable: Hear with confidence with Phonak CROS Infinio’s long-lasting rechargeable battery.","marks":[]}]},{"_type":"block","_key":"k2ua","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2u9","text":"Universal Connectivity: Universal connectivity allows seamless integration with Bluetooth® devices.","marks":[]}]},{"_type":"block","_key":"k2uc","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2ub","text":"Phonak Audéo Fit™","marks":[]}]},{"_type":"block","_key":"k2ue","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2ud","text":"Phonak Audéo Fit is an advanced hearing aid designed for active lifestyles. With its innovative features, Audéo Fit helps you build healthy habits by tracking distance, steps, activity levels, average wearing time, and heart rate through the myPhonak app. When it is connected to the myPhonak app, it can track and display your current and resting heart rates, as well as an overview of your heart rate on a daily, weekly, monthly, and yearly basis.","marks":[]}]},{"_type":"block","_key":"k2ug","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2uf","text":"Its Bluetooth connectivity allows seamless connection to smartphones, TVs, Roger™ devices, and more. Audéo Fit comes in two performance levels, Premium (P90) and Advanced (P70), ensuring it meets your specific lifestyle needs.","marks":[]}]},{"_type":"block","_key":"k2ui","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2uh","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2uk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2uj","text":"Health Data Tracker: It enables users to track metrics such as distance traveled, steps taken, activity levels, average wearing time of the hearing aid, and heart rate. This is accessed through the myPhonak app, providing users with valuable insights into their overall well-being and helping them to maintain healthy habits.","marks":[]}]},{"_type":"block","_key":"k2um","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2ul","text":"Tap Control: With this innovative feature, users can perform actions such as answering or ending phone calls, adjusting volume levels, changing programs, or activating other settings simply by tapping on their Audéo Fit hearing aid.","marks":[]}]},{"_type":"block","_key":"k2uo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2un","text":"Universal Connectivity: With universal connectivity, you can pair Audéo Fit with Bluetooth®-enabled smartphones, TVs, and Roger™ devices.","marks":[]}]},{"_type":"block","_key":"k2uq","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2up","text":"Phonak Audéo™ Lumity","marks":[]}]},{"_type":"block","_key":"k2us","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2ur","text":"Phonak understands that conversations are at the heart of life, and being able to fully engage in them is like a spark of light. Phonak Lumity was designed to allow speech to shine, even in those challenging listening situations. With the updated AutoSense Operating System (AutoSense OS) 5.0, Lumity was created with artificial intelligence-based machine learning to accurately identify a sound environment. By seamlessly adapting to different listening scenarios, Lumity is designed to maintain natural sound to improve your listening in everyday life.","marks":[]}]},{"_type":"block","_key":"k2uu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2ut","text":"Phonak Audéo Lumity hearing aids are appropriate for fitting mild to profound hearing losses. This device is a receiver-in-the-ear (RITE) model and is currently available in a rechargeable solution. Lumity is the second generation of the world’s first waterproof rechargeable hearing aid. This makes them an ideal hearing solution for people who live an active lifestyle and put their hearing aids to the test!","marks":[]}]},{"_type":"block","_key":"k2uw","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2uv","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2uy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2ux","text":"Bluetooth connectivity: Audéo Lumity pairs with the myPhonak app and Bluetooth-enabled devices to help you connect with the world around you.","marks":[]}]},{"_type":"block","_key":"k2v0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2uz","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2v2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2v1","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2v4","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2v3","text":"Phonak Slim","marks":[]}]},{"_type":"block","_key":"k2v6","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2v5","text":"The Phonak Slim device offers many of the same features as the Phonak Audéo Lumity but with a redefined design. The unique ergonomic shape of the Slim offers improved comfort and confidence in wearing a RITE style. Slim is crafted to fit naturally nestled behind the ear, even if you wear glasses.","marks":[]}]},{"_type":"block","_key":"k2v8","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2v7","text":"Phonak Slim hearing aids are appropriate for fitting mild to severe hearing loss. The device is a receiver-in-the-ear (RITE) style and is currently available in a rechargeable solution.","marks":[]}]},{"_type":"block","_key":"k2va","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2v9","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2vc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vb","text":"Bluetooth connectivity: Phonak Slim pairs with the myPhonak app and Bluetooth-enabled devices to help you connect with the world around you.","marks":[]}]},{"_type":"block","_key":"k2ve","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vd","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2vg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vf","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2vi","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2vh","text":"Phonak CROS Lumity","marks":[]}]},{"_type":"block","_key":"k2vk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vj","text":"Living with single-sided hearing loss or deafness creates several listening challenges. Listening to background noise and locating where sounds are coming from are just a few of the everyday difficulties. The Phonak CROS Lumity opens up a world where you can enjoy conversations no matter where they come from. The newest CROS technology allows you to immerse yourself and live in every moment with a hearing solution designed for those with unaidable hearing loss in one ear.","marks":[]}]},{"_type":"block","_key":"k2vm","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vl","text":"A contralateral routing of the signal (CROS) device is worn on an unaidable ear, to pick up sounds and transmit them wirelessly to the hearing aid worn on the better-hearing ear. The compatible Phonak hearing aid receives the signal from the unaidable ear and plays it to the aidable ear. CROS Lumity devices always need to be combined with a compatible hearing aid in order to function.","marks":[]}]},{"_type":"block","_key":"k2vo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vn","text":"The Phonak CROS Lumity hearing aid is appropriate for fitting one-sided hearing loss or single-sided deafness (SSD). This device is currently available in a rechargeable solution. Phonak CROS Lumity can be fitted with an Audéo L-R, Audéo L-RT, Naída L-PR, or Sky L-PR of any performance level.","marks":[]}]},{"_type":"block","_key":"k2vq","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vp","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2vs","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vr","text":"Bluetooth connectivity: The Phonak CROS Lumity pairs with the myPhonak app and Bluetooth-enabled devices to help you connect with the world around you.","marks":[]}]},{"_type":"block","_key":"k2vu","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vt","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2vw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2vv","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2vy","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2vx","text":"Phonak Naída Lumity","marks":[]}]},{"_type":"block","_key":"k2w0","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2vz","text":"The Phonak Naída Lumity hearing aid is the most powerful hearing solution for significant hearing loss. Their newest technology analyzes 700 environmental scans per second, translating to a high-fidelity sound quality that allows you to feel confident in navigating your everyday life. Naída Lumity embraces the power of conversations and delivers robust and reliable volume for individuals with significant hearing loss.","marks":[]}]},{"_type":"block","_key":"k2w2","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2w1","text":"Phonak Naída Lumity hearing aids are appropriate for fitting mild to profound hearing losses. They are a behind-the-ear (BTE) style and are currently available in a rechargeable solution, in addition to a size 675 disposable battery in the ultra-power (UP) model.","marks":[]}]},{"_type":"block","_key":"k2w4","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2w3","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2w6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2w5","text":"Bluetooth connectivity: Naída Lumity pairs with the myPhonak app and Bluetooth-enabled devices to help you connect with the world around you.","marks":[]}]},{"_type":"block","_key":"k2w8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2w7","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2wa","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2w9","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2wc","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2wb","text":"Phonak Sky Lumity","marks":[]}]},{"_type":"block","_key":"k2we","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wd","text":"Children deserve every opportunity to thrive in their various dynamic listening environments. From developing speech to succeeding academically, Phonak understands the importance of hearing in even the littlest of ears. The classroom, home, and extracurricular activities carry different hearing demands. Their state-of-the-art SmartSpeech™ Technology utilizes a variety of features that minimize unwanted sounds and prioritize speech understanding.","marks":[]}]},{"_type":"block","_key":"k2wg","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wf","text":"Phonak Sky Lumity hearing aids are appropriate for fitting mild to profound hearing losses. Sky Lumity is a behind-the-ear (BTE) style and is currently available in a rechargeable solution, in addition to a size 675 disposable battery in the ultra-power (UP) model. They also offer Sky Link M, which is a BTE hearing aid designed to support younger children from the very beginning.","marks":[]}]},{"_type":"block","_key":"k2wi","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wh","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2wk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wj","text":"Bluetooth connectivity: Sky Lumity pairs with the myPhonak Junior app and Bluetooth-enabled devices to help you connect with the world around you. Universal connectivity allows your child to enjoy listening to their personal devices.","marks":[]}]},{"_type":"block","_key":"k2wm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wl","text":"Personalization: The myPhonak Junior app is the industry’s only dedicated pediatric app, and empowers children to personalize their hearing experience. It gives children and parents access to wearing time, but also lets children take control of the sound around them and personalize their settings in the real world.","marks":[]}]},{"_type":"block","_key":"k2wo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wn","text":"Tamper-resistant: Phonak provides styles that help keep the battery out of reach of curious fingers.","marks":[]}]},{"_type":"block","_key":"k2wq","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2wp","text":"Phonak Virto Paradise","marks":[]}]},{"_type":"block","_key":"k2ws","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wr","text":"Phonak Virto Paradise is an in-the-ear (ITE) hearing aid designed just for you. This product line is equipped with several features that optimize your hearing experience by minimizing unwanted noise and enhancing speech. The custom-tailored fit allows your hearing aid to mirror the exact shape of your ear, resulting in a more discreet design and easier to wear with glasses.","marks":[]}]},{"_type":"block","_key":"k2wu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wt","text":"Phonak Virto Paradise hearing aids are appropriate for fitting mild to severe hearing losses. It is an ITE model and is currently available in a variety of sizes: in-the-canal (ITC), completely-in-the-canal (CIC), and invisible-in-the-canal (IIC). The model is available in a variety of color choices, including a black design to resemble modern earbuds. There are a variety of disposable battery options to choose from, depending on the size of the device.","marks":[]}]},{"_type":"block","_key":"k2ww","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2wv","text":"Unique Features:","marks":[]}]},{"_type":"block","_key":"k2wy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wx","text":"Bluetooth connectivity: Virto Paradise ITE and ITC devices connect to smartphones, TVs, and more to keep up with your busy life. Additionally, you can easily switch between two paired devices with enhanced Bluetooth capabilities. Smaller products, such as the CIC and IIC, offer streaming via Phonak accessories.","marks":[]}]},{"_type":"block","_key":"k2x0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2wz","text":"Personalization: The myPhonak app is a free, easy-to-use smartphone app that empowers you to take control of your hearing. This allows you to directly connect to your Phonak hearing aids for volume control, program adjustments, and more.","marks":[]}]},{"_type":"block","_key":"k2x2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2x1","text":"Remote Help: The myPhonak app also allows you to connect virtually to remotely schedule a visit with your hearing care professional to address your hearing aid concerns.","marks":[]}]},{"_type":"block","_key":"k2x4","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2x3","text":"Assistive Listening Devices & Technology by Phonak","marks":[]}]},{"_type":"block","_key":"k2x6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2x5","text":"Roger On: A unique microphone for everyday use in noise and over distance. It recognizes if speech is coming from the left or right side of the wearer and provides spatial information to complete the picture of your listening environment.","marks":[]}]},{"_type":"block","_key":"k2x8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2x7","text":"Roger Select: Roger Select is a versatile Bluetooth microphone for hearing aids that is ideal for stationary situations where background noise is present. When used as a table mic, it discreetly and automatically selects the person who is talking and seamlessly switches from one talker to another.","marks":[]}]},{"_type":"block","_key":"k2xa","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2x9","text":"Phonak Serenity Choice: High-end hearing protection solution designed to reduce noise and loud sounds while allowing the ear to breathe and maintain relevant sound and speech information.","marks":[]}]},{"_type":"block","_key":"k2xc","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2xb","text":"Phonak offers additional accessories to enhance your hearing aid experience:","marks":[]}]},{"_type":"block","_key":"k2xe","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xd","text":"Table Mic II","marks":[]}]},{"_type":"block","_key":"k2xg","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xf","text":"Roger Focus II","marks":[]}]},{"_type":"block","_key":"k2xi","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xh","text":"Roger for Education","marks":[]}]},{"_type":"block","_key":"k2xk","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xj","text":"Clip-on Mic","marks":[]}]},{"_type":"block","_key":"k2xm","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xl","text":"TV Connector","marks":[]}]},{"_type":"block","_key":"k2xo","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xn","text":"PartnerMic","marks":[]}]},{"_type":"block","_key":"k2xq","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xp","text":"Remote Control","marks":[]}]},{"_type":"block","_key":"k2yg","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2yf","text":"Frequently Asked Questions About Phonak Hearing Aids","marks":[]}]},{"_type":"block","_key":"k2yi","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2yh","text":"What are the different levels of Phonak Lumity?","marks":[]}]},{"_type":"block","_key":"k2yk","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2yj","text":"Phonak Lumity offers four different technology levels, including the following: L90, L70, L50, and L30, ranging from the highest to the lowest technology levels, respectively.","marks":[]}]},{"_type":"block","_key":"k2ym","style":"h3","markDefs":[],"children":[{"_type":"span","_key":"k2yl","text":"What is the difference between Phonak Paradise and Phonak Life hearing aids?","marks":[]}]},{"_type":"block","_key":"k2yo","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2yn","text":"The world’s first waterproof rechargeable hearing aid, Audéo Life, combines the hearing performance of Audéo Paradise with a robust new housing that provides additional protection from water and sweat.","marks":[]}]},{"_type":"block","_key":"k2xs","style":"h2","markDefs":[],"children":[{"_type":"span","_key":"k2xr","text":"Older Phonak Hearing Aid Models Supported By New Leaf Hearing Care In Colorado","marks":[]}]},{"_type":"block","_key":"k2xu","style":"normal","markDefs":[],"children":[{"_type":"span","_key":"k2xt","text":"These hearing aid models may still be supported for hearing aid servicing and repair by New Leaf Hearing Care. Please contact us for more information.","marks":[]}]},{"_type":"block","_key":"k2xw","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xv","text":"Phonak Audéo Paradise","marks":[]}]},{"_type":"block","_key":"k2xy","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xx","text":"Phonak Naída Paradise","marks":[]}]},{"_type":"block","_key":"k2y0","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2xz","text":"Phonak CROS Paradise","marks":[]}]},{"_type":"block","_key":"k2y2","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y1","text":"Phonak Naída Link Marvel","marks":[]}]},{"_type":"block","_key":"k2y4","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y3","text":"Phonak Sky Marvel","marks":[]}]},{"_type":"block","_key":"k2y6","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y5","text":"Phonak Audéo Marvel","marks":[]}]},{"_type":"block","_key":"k2y8","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y7","text":"Phonak Bolero B","marks":[]}]},{"_type":"block","_key":"k2ya","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2y9","text":"Phonak Naída B","marks":[]}]},{"_type":"block","_key":"k2yc","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2yb","text":"Phonak Virto B","marks":[]}]},{"_type":"block","_key":"k2ye","style":"normal","listItem":"bullet","level":1,"markDefs":[],"children":[{"_type":"span","_key":"k2yd","text":"Phonak Audéo B","marks":[]}]}]';
